import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { evaluate, parseRig } from "../src/index.js";
import type { AnimationLayer } from "../src/index.js";

interface Reference {
  source: string;
  tolerance: number;
  rig: unknown;
  cases: Array<{
    layers: AnimationLayer[];
    bones: Array<{ name: string; local: number[]; world: number[] }>;
  }>;
}

test("native v2 export agrees with Rust locals and world affines on the same fixtures", () => {
  // This file is generated by editor/export/examples/runtime_axes_parity.rs.
  // The live cross-repository check rejects stale snapshots after Rust changes.
  const reference = JSON.parse(readFileSync(
    new URL("../../test/fixtures/runtime_axes_parity.json", import.meta.url), "utf8",
  )) as Reference;
  const rig = parseRig(reference.rig);
  assert.equal(rig.format_version, 2);
  assert.equal(reference.tolerance, 0.01);
  assert.equal(reference.cases.length, 128);
  let maxError = 0;
  let comparisons = 0;
  for (const entry of reference.cases) {
    const pose = evaluate(rig, entry.layers);
    for (const expected of entry.bones) {
      const bone = pose.bones.find((candidate) => candidate.name === expected.name)!;
      const local = [bone.x, bone.y, bone.rotation, bone.scaleX, bone.scaleY, bone.shearX, bone.shearY];
      const world = [bone.world.a, bone.world.b, bone.world.c, bone.world.d, bone.world.tx, bone.world.ty];
      for (const [actual, wanted, label] of [[local, expected.local, "local"], [world, expected.world, "world"]] as const) {
        assert.equal(actual.length, wanted.length);
        actual.forEach((value, index) => {
          const error = Math.abs(value - wanted[index]!);
          assert.ok(Number.isFinite(error) && error <= reference.tolerance,
            `${JSON.stringify(entry.layers)} ${bone.name} ${label}[${index}]: ${value} vs Rust ${wanted[index]}`);
          maxError = Math.max(maxError, error);
          comparisons += 1;
        });
      }
    }
  }
  console.info(`Rust/TypeScript parity: ${reference.cases.length} cases, ${comparisons} components, max absolute error ${maxError}`);
});
